package com.bank.watchlist;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.HashMap;
import java.util.Map;

// Finds the next greater price to the right using a monotonic stack.
public class NextGreaterPriceFinder {

    // For each value in query, return the first larger value to its
    // right in series; -1 if none. query is a subset of series.
    public int[] nextGreater(int[] query, int[] series) {
        Map<Integer, Integer> nextGreaterMap = new HashMap<>();
        Deque<Integer> stack = new ArrayDeque<>(); // decreasing from bottom to top

        for (int price : series) {
            // Current price resolves every smaller pending price.
            while (!stack.isEmpty() && price > stack.peek()) {
                nextGreaterMap.put(stack.pop(), price);
            }
            stack.push(price); // now waiting for its own next greater
        }
        // Remaining prices have no greater element to the right.
        while (!stack.isEmpty()) {
            nextGreaterMap.put(stack.pop(), -1);
        }

        int[] result = new int[query.length];
        for (int i = 0; i < query.length; i++) {
            result[i] = nextGreaterMap.getOrDefault(query[i], -1);
        }
        return result;
    }
}
