package com.bank.watchlist;

import java.util.Arrays;
import java.util.logging.Logger;

// Answers next-greater-price queries for a watchlist subset.
public class WatchlistService {

    private static final Logger log = Logger.getLogger(WatchlistService.class.getName());
    private final NextGreaterPriceFinder finder;

    public WatchlistService(NextGreaterPriceFinder finder) {
        this.finder = finder;
    }

    public int[] breakoutPrices(int[] watchlist, int[] fullSeries) {
        int[] answers = finder.nextGreater(watchlist, fullSeries);
        log.info(() -> "Watchlist " + Arrays.toString(watchlist)
                + " next-greater prices = " + Arrays.toString(answers));
        return answers;
    }
}
