package com.bank.watchlist;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class NextGreaterDemo {

    private static final Logger log = Logger.getLogger(NextGreaterDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Watchlist Breakout Finder");
        WatchlistService service = new WatchlistService(new NextGreaterPriceFinder());

        int[] fullSeries = {2450, 2400, 2500, 2460, 2600};
        int[] watchlist = {2400, 2500, 2600};
        // 2400 → 2500, 2500 → 2600, 2600 → -1
        service.breakoutPrices(watchlist, fullSeries);
    }
}
